insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-four-checkouts-on-measured-disk-s691','decision','Four worker checkouts at once on measured disk','S691 conductor: four worker checkouts ran at once, above the three of S653''s smaller disk, because the disk was measured first: 1.5 GB a checkout and 58 GB free at 07:18Z. A finished worker''s checkout is removed once its head is pushed (repo-size lane). Reversible: the next run measures again and sets its own count.',array['conductor','workers','disk'],'proposed','docs/session_697_handoff.md','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('d-canyons-nc-read-pays-v2-rereads-s691','decision','College of the Canyons'' noncredit read paid for its relisted Catalog-v2 records','S691 conductor: the free pricing run 44886119075 estimated $21.90 for 196 programs, 103 of them old Catalog-v2 records relisted (f-would-extract-relists-same-page-s691). The college workflow has no only input, so the estimate was paid rather than build tooling in a collection run: $12.88 actual (extract 44886816990). Keep-the-better kept the better record of each.',array['program-requirements','conductor','spend'],'proposed','#3634','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('d-ccsf-20-not-named-s691','decision','City College of San Francisco''s 20 not-printed programs stay unnamed','S691 conductor: the not_printed_current_or_prior rule was dropped after its second read. The 2025-26 extract read 7 of the 27 not-printed programs (prior.only), so the other 20 were never put to the rule and take no named gap. They stay not printed in kb/status/program_discontinued.json until another source prints them. #3633.',array['program-requirements','ccsf','named-gaps'],'proposed','#3633','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('d-generated-files-built-with-runner-python-s691','decision','Generated files are built with the runner''s Python, 3.12','S691 conductor: a committed file CI regenerates is built with /usr/bin/python3.12, CI''s version, and check_generated.sh runs with a python3 symlink to 3.12 first on PATH. #3602''s commons_data.json, built on the sandbox''s 3.11, failed CI on one rounded mean; #3633 moved the builder''s float sums to math.fsum. Note: methodology-a-generated-file-is-built-with-the-runners-python.',array['ci','generated-files','python'],'proposed','docs/kb-notes/methodology-a-generated-file-is-built-with-the-runners-python.md','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('d-merge-on-clean-when-files-disjoint-s691','decision','A PR whose files are disjoint from the last merge''s merges without a second update','S691 conductor: #3635 (the display page file) merged on a clean state without a second update from main after #3633 merged, since #3633 touched no file #3635 holds. The one update from main right before a merge still stands wherever the two PRs'' files overlap.',array['conductor','merge','branch-policy'],'proposed','#3635','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('d-golden-west-before-values-filed-s691','decision','Golden West''s before-values filed ahead of any correction','S691 conductor: the before-values of Golden West''s 476 outline rows that hold a heading are filed first (476 rows, checksum cb441aa1, live read 44881579974; plan on claude/s690-goldenwest-header 0995d8b5), so a rollback undoes the correction row by row. The guarded correction does not run in a collection night; it waits on a plain session''s review.',array['course-outcomes','golden-west','rule-10'],'proposed','claude/s690-goldenwest-header 0995d8b5','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-would-extract-relists-same-page-s691','fact','The pricing step relists a page the reread gate calls the same','S691: would_extract''s filed_from compares source_url literally, so College of the Canyons'' 103 records filed from its 2026-27 Catalog v2 were priced as new pages once the catalog moved to v3. It should honor d-reread-gate-same-page-calls-s690, under which a new edition of the same catalog counts as the same page. The free pricing run caught it before any money moved.',array['program-requirements','reread','spend'],'proposed','#3634; pricing run 44886119075','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-timed-out-read-still-files-s691','fact','A timed-out read still files its records','S691: Santa Monica''s read 44883500729 timed out, and its filing step still committed, dropping 46 records from the branch. The conductor reverted it (6ba61a4c) and ran a second read (44885033145, $1.72). The filing step should refuse a run that timed out.',array['program-requirements','santa-monica','reader'],'proposed','#3633','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-py312-sum-rounds-differently-s691','fact','Python 3.12''s sum() rounds floats differently from 3.11''s','S691: Python 3.12 sums floats with compensated (Neumaier) summation and 3.11 does not, so kb/status/commons_data.json built on the sandbox''s 3.11 carried a statewide mean of 0.6544 where CI''s 3.12 build gave 0.6543, and #3602''s generated check failed. math.fsum is exact on both (#3633).',array['ci','generated-files','python'],'proposed','#3602; #3633','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-sjdelta-apprenticeship-coarse-net-s691','fact','San Joaquin Delta''s apprenticeship records read at full coverage and are refused','S691: San Joaquin Delta''s apprenticeship programs 14594 to 14599 and 37611 read at coverage 1.0, yet the coarse net refuses them, so they do not pass. An unmeasured lever: measure it free on the filed records before any change.',array['program-requirements','san-joaquin-delta','lever'],'proposed','#3634','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-hond-045-fold-s691','fact','Rio Hondo''s HOND 045 and HOND 045-1 fold into one code','S691: Rio Hondo''s outline index lists HOND 045 and HOND 045-1, and the reader folds the two into one course code, so one course''s outline could be filed under the other''s. Worker outlines2 fixes the fold in its PR.',array['course-outcomes','rio-hondo','reader'],'proposed','docs/session_697_handoff.md','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-ccsf-outline-gate-stale-on-main-s691','fact','City College of San Francisco''s outline recall gate is stale on main','S691: on main, City College of San Francisco''s outline recall gate reads fingerprint 8c95dee8 against the d5cef493 of the trial its hand counts came from (#3601). The gate refuses a fingerprint mismatch, so refresh it before the college''s next outline read.',array['course-outcomes','ccsf','recall-gate'],'proposed','docs/session_697_handoff.md','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-outline-ranking-s691','fact','Outline readers ranked by the M-ID cards each improves','S691''s read-only M-ID count ranked the outline readers by the cards each would improve: Saddleback 1,120, Rio Hondo 871, Irvine Valley 735, San Diego College of Continuing Education 191, Golden West 50. Saddleback and Rio Hondo ran first (worker outlines2).',array['course-outcomes','m-id','collection'],'proposed','docs/session_697_handoff.md','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-still-taught-hand-ins-no-outline-text-s691','fact','The still-taught courses'' hand-ins carry no outline text','S691: the hand-ins for the 12 still-taught courses (North Orange Continuing Education, Southwestern, Grossmont; Ohlone''s four print nothing) carry no outline text to read, so their SLOs and objectives wait on a person''s paste or another source.',array['course-outcomes','hand-filed','collection'],'proposed','docs/session_697_handoff.md','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('f-cheap-piles-shapes-s691','fact','The cheap piles measured at five colleges','S691 lane 2, no writes: Santa Monica''s 12 lists run past their printed figure (238 statewide), 16 are mixed; Glendale''s 33: 11 with no record file, 18 unequal; Clovis 42234 needs a p.121 pin, 33431 is a named-gap candidate; Lake Tahoe''s 13 sit on quarter units with no ruling; of the noncredit hours lever''s 68, 19 print no total, 7 sum to zero, 2 one figure against a range, 40 other.',array['program-requirements','cheap-piles','lever'],'proposed','docs/program_requirements_harvest_lessons.md (S691)','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('p-clock-guard-guessed-time-s691','pitfall','The clock guard refuses a guessed time','S691: a time written as 08:20Z when the clock read 08:17Z was refused by the clock guard. Read date -u before writing any time into a handoff, a lane, a receipt or a comment.',array['conductor','clock','guards'],'proposed','docs/reference/conductor_mode.md (S691)','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('p-shared-git-shallow-lock-s691','pitfall','Worktrees share one .git and its shallow lock','S691: worker checkouts under .claude/worktrees share one .git, so a depth fetch in one holds shallow.lock for all and another''s fetch fails. Confirm a merge with git ls-remote rather than a fetch, and never delete the lock.',array['conductor','git','workers'],'proposed','docs/reference/conductor_mode.md (S691)','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('p-actions-log-host-blocked-s691','pitfall','The Actions log host is blocked from the sandbox','S691: a job''s raw log sits on a host the sandbox proxy refuses, so fetching it fails. Read a job''s tail with the github tools'' get_job_logs instead.',array['conductor','ci','sandbox'],'proposed','docs/reference/conductor_mode.md (S691)','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('p-one-concern-per-worker-context-s691','pitfall','One concern per worker: a second task ran one out of context','S691: worker piles took #3602''s update and then the cheap piles, and ran out of context in its second task; piles2 and piles3 finished lane 2. Give each worker one concern and start a fresh worker for the next.',array['conductor','workers','context'],'proposed','docs/reference/conductor_mode.md (S691)','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('p-census-commit-turns-main-red-s691','pitfall','A census commit on main can turn test red with no PR open','S691: #3602 made the census job''s full build set the spend file''s updated to the day it writes, while tests/spend_daily_build_test.py still pinned it to 2026-11-15. The first census after it (c1700e76) failed main''s lints job (run 44893759916) and every head carrying it. Read main''s own run after each census; the S691 checkpoint branch pins the day''s shape and floor instead.',array['ci','census','tests'],'proposed','run 44893759916; tests/spend_daily_build_test.py','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('m-wave-posts-s691','milestone','109 program records added and 201 replaced by a better reread','S691 (#3634 f46f65e7, #3633 b6d52c8e): the reread plan''s rows 56 to 73, College of the Canyons'' noncredit codes and prefix aliases, San Joaquin Delta, Solano and Santa Monica''s pinned pages: 109 new, 201 replaced, 24 re-posted, 5 restored, 2 held for a person (College of the Canyons 43388, West Los Angeles 46261), for $17.70 of extraction.',array['program-requirements','reread','collection'],'proposed','#3634; #3633','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('m-display-build-live-s691','milestone','Display build e35ae1722a56 is live','S691 (#3635 ca45115f): display build e35ae1722a56 replaced ac082e9d96dc. College of the Canyons first (44890523187, 246 of 246), the gate 44890803467, the whole build 44890972799 (18,363 written, 0 errors), the closing count 44891433372 (18,609 rows at the build). 32 rows stay at older builds, the same 32 as S690.',array['program-requirements','display','sierra'],'proposed','#3635; run 44891433372','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21'),
('m-census-4875-s691','milestone','Gap census: 4,875 of 20,282 active programs left','S691: harvest-gap-census.yml run 44892712171 (10:10Z, main c1700e76) counts 4,875 of 20,282 active programs without a passing record and 15,314 passing, from 4,982 and 15,207 at the night''s start.',array['program-requirements','census','collection'],'proposed','run 44892712171; kb/status/harvest_gap_census.json','SkyPetrel (S691), the conductor',null,'SkyPetrel (S691)',date '2026-11-21')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
